  // Computed warnings so broad or lumped hand-entered rows are never mistaken for generation-specific data.
  function noteFor(r, o) {
    var n = o.note || '', extra = [];
    if (!o.agg && r[3] - r[2] >= 8) extra.push('BROAD YEAR RANGE (' + (r[3] - r[2] + 1) + ' model years): values are a blend and may cross a redesign; prefer a generation-specific entry if listed.');
    if (!o.agg && / \/ /.test(r[1])) extra.push('LUMPED ENTRY: several models share this row, so values are not specific to one model.');
    return extra.length ? (n ? n + ' ' : '') + extra.join(' ') : n;
  }

  // A row is OEM-verified only with an https primary-source URL, a source model year inside the row's
  // year range, and an explicit verified flag. Verified rows are still never a clearance verdict:
  // the engine requires on-scene measurements for that.
  function isVerified(o, r) {
    return o.verified === true && /^https:\/\//.test(o.source || '') && o.sourceYear >= r[2] && o.sourceYear <= r[3] && !o.agg;
  }

  function toVehicle(r, i) {
    var o = r[11] || {};
    // Every current catalog row is pending source-level verification. A plausible
    // number or short year span is not evidence of an OEM specification. Keep all
    // catalog-derived recommendations low-confidence until a row has explicit,
    // auditable source provenance and a reviewed configuration scope.
    // This deliberately requires on-scene measurement before committing to load.
    return {
      id: 'v' + i,
      make: r[0], model: r[1], yFrom: r[2], yTo: r[3], body: r[4],
      drives: r[5].split('|'), power: r[6], trans: r[7].split('|'),
      curb: r[8], wb: r[9] || 0, gc: r[10] || 0,   // 0 = not in source / unknown (never a measured value)
      len: o.len || 0, wid: o.wid || 0, ht: o.ht || 0,
      gvwr: o.gvwr || 0, dually: !!o.dually, air: o.air || false,
      low: !!o.low, note: noteFor(r, o), source: o.source || '', sourceYear: o.sourceYear || 0, agg: o.agg || '', conf: isVerified(o, r) ? 1 : 0
    };
  }

  var vehicles = ROWS.map(toVehicle);
  var seen = {};
  var makes = vehicles.map(function (v) { return v.make; }).filter(function (m) {
    if (seen[m]) return false; seen[m] = true; return true;
  }).sort();

  return { ROWS: ROWS, vehicles: vehicles, makes: makes, toVehicle: toVehicle };
